    return products["category"].value_counts(normalize=normalize, dropna=True)


def top_categories(products, n=3):
    counts = _counts(products).head(n)
    return pd_frame(counts.index, counts.to_numpy())


def pd_frame(categories, counts):
    import pandas as pd

    return pd.DataFrame(
        {"category": list(categories), "count": list(counts)}
    ).reset_index(drop=True)


def category_share(products):
    shares = _counts(products, normalize=True)
    return {cat: round(float(share), 3) for cat, share in shares.items()}

