    text = "profile: dev\ndebug: true\n---\nprofile: prod\nworkers: 4\n"
    assert load_profiles(text) == {
        "dev": {"host": "localhost", "port": 8000, "debug": True, "workers": 1},
        "prod": {"host": "localhost", "port": 8000, "debug": False, "workers": 4},
    }

